import base64
import binascii

def _t():
    tests = ((b'%3d==', b'\xdd'), (b'$3d==', b'\xdd'), (b'[==', b''), (b'YW]3=', b'am'), (b'3{d==', b'\xdd'), (b'3d}==', b'\xdd'), (b'@@', b''), (b'!', b''), (b'YWJj\n', b'abc'), (b'YWJj\nYWI=', b'abcab'))
    funcs = (base64.b64decode, base64.standard_b64decode, base64.urlsafe_b64decode)
    for bstr, res in tests:
        for func in funcs:
            assert func(bstr) == res, ('assertEqual', func(bstr), res)
            assert func(bstr.decode('ascii')) == res, ('assertEqual', func(bstr.decode('ascii')), res)
        try:
            base64.b64decode(bstr, validate=True)
        except binascii.Error as _exc:
            pass
        else:
            raise AssertionError('assertRaises: did not raise')
        try:
            base64.b64decode(bstr.decode('ascii'), validate=True)
        except binascii.Error as _exc:
            pass
        else:
            raise AssertionError('assertRaises: did not raise')
    res = b'\xfb\xef\xff'
    assert base64.b64decode(b'++//', validate=True) == res, ('assertEqual', base64.b64decode(b'++//', validate=True), res)
    assert base64.b64decode(b'++//', '-_', validate=True) == res, ('assertEqual', base64.b64decode(b'++//', '-_', validate=True), res)
    assert base64.b64decode(b'--__', '-_', validate=True) == res, ('assertEqual', base64.b64decode(b'--__', '-_', validate=True), res)
    assert base64.urlsafe_b64decode(b'++//') == res, ('assertEqual', base64.urlsafe_b64decode(b'++//'), res)
    assert base64.urlsafe_b64decode(b'--__') == res, ('assertEqual', base64.urlsafe_b64decode(b'--__'), res)
try:
    _t()
